CREATE TABLE union_pnl_transaction_frames(transaction_id xid8 PRIMARY KEY,observed_at timestamptz NOT NULL,book_start timestamptz NOT NULL);
 CREATE TABLE union_pnl_cash_outcomes(table_id uuid NOT NULL,hand_number bigint NOT NULL,hand_id uuid NOT NULL UNIQUE,transaction_id xid8 NOT NULL REFERENCES union_pnl_transaction_frames(transaction_id),recognized_at timestamptz NOT NULL,payload_hash text NOT NULL,game_scope jsonb NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(table_id,hand_number));
 CREATE INDEX outcomes_week ON union_pnl_cash_outcomes((game_scope->>'game_union_id'),recognized_at);
 CREATE INDEX outcomes_unaccepted ON union_pnl_cash_outcomes((game_scope->>'game_union_id'),recognized_at) WHERE evidence->>'status' IS DISTINCT FROM 'ready' OR evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb OR evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR evidence->'game_scope' IS DISTINCT FROM game_scope;
 CREATE TABLE union_pnl_cash_outcome_touches(table_id uuid NOT NULL,hand_number bigint NOT NULL,recognized_at timestamptz,game_union_id text,shaped boolean NOT NULL,accepted_rake text,participants jsonb,PRIMARY KEY(table_id,hand_number));
 CREATE INDEX union_pnl_cash_outcome_touches_week ON union_pnl_cash_outcome_touches(game_union_id,recognized_at);
CREATE TABLE public.union_pnl_cash_outcome_link_resolutions (
  table_id uuid NOT NULL,
  hand_number bigint NOT NULL,
  hand_id uuid NOT NULL,
  outcome_payload_hash text NOT NULL,
  outcome_evidence_md5 text NOT NULL CHECK (outcome_evidence_md5 ~ '^[0-9a-f]{32}$'),
  roster_source text NOT NULL CHECK (roster_source IN ('manifest','seat_inventory')),
  manifest_id uuid,
  game_scope jsonb NOT NULL CHECK (jsonb_typeof(game_scope)='object'
    AND game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale']),
  evidence jsonb NOT NULL CHECK (jsonb_typeof(evidence)='object' AND evidence->>'provenance_link'='resolved'),
  proof jsonb NOT NULL,
  proof_md5 text NOT NULL,
  reason text NOT NULL CHECK (length(btrim(reason)) >= 20),
  resolved_by text NOT NULL DEFAULT session_user,
  resolved_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  PRIMARY KEY (table_id, hand_number),
  UNIQUE (hand_id),
  CHECK (proof_md5 = md5(proof::text)),
  CHECK ((roster_source='manifest') = (manifest_id IS NOT NULL)),
  CHECK (proof->>'status'='proven' AND proof->>'resolution_kind'='cash_outcome_provenance_link'
    AND proof->>'table_id'=table_id::text AND (proof->>'hand_number')::bigint=hand_number AND proof->>'hand_id'=hand_id::text
    AND proof->>'outcome_payload_hash'=outcome_payload_hash AND proof->>'outcome_evidence_md5'=outcome_evidence_md5
    AND proof->>'roster_source'=roster_source AND proof->>'manifest_id' IS NOT DISTINCT FROM manifest_id::text
    AND proof->'game_scope'=game_scope AND proof->'evidence'=evidence AND evidence->'game_scope'=game_scope)
);
